package dominoes

// Domino represents a single domino stone: the number of dots on each half.
type Domino [2]int

// MakeChain computes a way to order the given set of dominoes such that they
// form a correct domino chain: the dots on one half of a stone match the dots
// on the neighboring half of an adjacent stone, and the two unpaired ends
// (the first and last stone) match each other.
//
// It returns the chain and true if one exists, or nil and false otherwise.
// An empty input is considered a legal (empty) chain.
func MakeChain(input []Domino) ([]Domino, bool) {
	chain, ok := makeChain(input)
	if !ok {
		return nil, false
	}
	return chain, true
}

// makeChain searches for a closed chain (a cycle) using all the given
// dominoes, via backtracking over the dominoes and their orientations.
func makeChain(input []Domino) ([]Domino, bool) {
	for i := range input {
		for _, start := range orientations(input[i]) {
			if chain, ok := extend(start[0], start, without(input, i)); ok {
				return append([]Domino{start}, chain...), true
			}
		}
	}
	return nil, false
}

// extend appends dominoes from rest to a chain whose first number is start
// and whose current open end is last[1]. It returns the remaining (not yet
// tried) chain and true once every domino has been placed and the open end
// meets the start, closing the cycle.
func extend(start int, last Domino, rest []Domino) ([]Domino, bool) {
	if len(rest) == 0 {
		return nil, last[1] == start
	}
	for i := range rest {
		d := rest[i]
		if d[0] == last[1] {
			if chain, ok := extend(start, d, without(rest, i)); ok {
				return append([]Domino{d}, chain...), true
			}
		}
		if d[1] == last[1] && d[0] != d[1] {
			f := Domino{d[1], d[0]}
			if chain, ok := extend(start, f, without(rest, i)); ok {
				return append([]Domino{f}, chain...), true
			}
		}
	}
	return nil, false
}

// orientations returns the distinct ways of orienting a domino. Doubles have
// only one orientation.
func orientations(d Domino) []Domino {
	if d[0] == d[1] {
		return []Domino{d}
	}
	return []Domino{d, {d[1], d[0]}}
}

// without returns a copy of ds with the element at index i removed.
func without(ds []Domino, i int) []Domino {
	out := make([]Domino, 0, len(ds)-1)
	out = append(out, ds[:i]...)
	return append(out, ds[i+1:]...)
}

